<script setup lang="ts">
import HouseholdName from '../../Components/HouseholdName.vue';import ProfilePreferences from '../../Components/ProfilePreferences.vue';import SelectField from '../../Components/SelectField.vue';import LoanWorkspace from '../../Components/LoanWorkspace.vue';import InvestmentWorkspace from '../../Components/InvestmentWorkspace.vue';
import {computed,ref,watch} from 'vue';import {Head,Link,router,usePage} from '@inertiajs/vue3';
import {Plus,ChevronLeft,ChevronRight,Search,Check,Pencil,Trash2,History,Wallet,ReceiptText,CalendarDays,Users,RefreshCw,Unplug,Bell,Eye,EyeOff,CheckCheck,X,Landmark} from 'lucide-vue-next';
import AppLayout from '../../Layouts/AppLayout.vue';import FinanceEditor from '../../Components/FinanceEditor.vue';import OccurrencePanel from '../../Components/OccurrencePanel.vue';import Modal from '../../Components/Modal.vue';import Pagination from '../../Components/Pagination.vue';import BalanceChart from '../../Components/BalanceChart.vue';import HistoryPanel from '../../Components/HistoryPanel.vue';
import InvitationReview from '../../Components/InvitationReview.vue';
import AssignmentFilter from '../../Components/AssignmentFilter.vue';
import SubscriptionWorkspace from '../../Components/SubscriptionWorkspace.vue';import AccountDetails from '../../Components/AccountDetails.vue';import TransactionDetails from '../../Components/TransactionDetails.vue';import ConnectionDetails from '../../Components/ConnectionDetails.vue';import LoanChart from '../../Components/LoanChart.vue';
import {money,dateLabel,monthLabel,shiftMonth,iso,json} from '../../lib/format';
const props=withDefaults(defineProps<{section:string;records:any;catalog?:any;month?:string;summary?:any;calendarStart?:string;weeks?:any[];history?:any[];contributions?:any;selectedCategory?:string;invitations?:any[];connections?:any[];providerReady?:boolean;profile?:any;filters?:any;limits?:any[];breakdown?:any[];setup?:any;investment?:any}>(),{catalog:()=>({accounts:[],categories:[],members:[]}),weeks:()=>[],history:()=>[],invitations:()=>[],connections:()=>[]});
const page=usePage<any>();const items=computed<any[]>(()=>Array.isArray(props.records)?props.records:props.records?.data||[]);
const title:Record<string,string>={home:'Home',budget:'Budget',bills:'Bills',income:'Income',subscriptions:'Subscriptions',accounts:'Accounts',loans:'Loans',transactions:'Transactions',investments:'Investments',categories:'Categories',household:'Household',profile:'Profile',notifications:'Notifications'};
const subtitles:Record<string,string>={home:'A clearer picture of your month.',budget:'Actual spending from transactions. Monthly targets in USD · UTC.',bills:'Plan bills and recurring payments.',income:'Plan expected income and track what arrives.',subscriptions:'Recurring costs, all in one place.',accounts:'Balances, debts, and your shared financial picture.',loans:'Every step toward paying it off.',transactions:'Your financial activity, with context.',investments:'Provider-reported holdings and valuations.',categories:'Organize spending and income your way.',household:'Your people, settings, and bank connections.',profile:'Your personal reminder preferences.',notifications:'Updates and reminders for you.'};
const editor=ref<any>();const occurrence=ref<string>();const drawer=ref<any>();const day=ref<string>();const loadingError=ref('');
const transactionPanel=ref<InstanceType<typeof TransactionDetails>>();const selectedTransaction=ref<string>();const collapsedCategories=ref<string[]>([]);
watch(()=>[props.records,props.section],()=>{if(props.section==='transactions'&&!items.value.some(t=>t.id===selectedTransaction.value))selectedTransaction.value=items.value[0]?.id;},{immediate:true});
function toggleCategory(id:string){collapsedCategories.value=collapsedCategories.value.includes(id)?collapsedCategories.value.filter(value=>value!==id):[...collapsedCategories.value,id];}
const addAccountMenu=ref(false);const invitationReview=ref<string>();const accountDetail=ref<string>(),transactionDetail=ref<string>(),connectionDetail=ref<string>();const categoryTab=ref('expense');const showCanceled=ref(Boolean(Number(props.filters?.show_canceled||0)));const showPaidLoans=ref(Boolean(Number(props.filters?.show_paid||0)));
const search=ref(props.filters?.search||'');const listView=ref(false);const hidePaid=ref(false);const showHidden=ref(Boolean(Number(props.filters?.show_hidden||0)));const accountFilter=ref(props.filters?.account||'');const categoryFilter=ref(props.filters?.category||'');
const assignmentFilter=ref(props.filters?.assignment||'');
watch(()=>[props.section,props.filters],()=>{assignmentFilter.value=props.filters?.assignment||'';search.value=props.filters?.search||'';showCanceled.value=Boolean(Number(props.filters?.show_canceled||0));showPaidLoans.value=Boolean(Number(props.filters?.show_paid||0));});
const days=computed(()=>{if(!props.calendarStart)return [];const start=new Date(props.calendarStart+'T12:00:00Z');return Array.from({length:(props.weeks.length||5)*7},(_,i)=>{const d=new Date(start);d.setUTCDate(d.getUTCDate()+i);return iso(d);});});
const visibleItems=computed(()=>items.value.filter(i=>i.kind==='income'||!hidePaid.value||i.status!=='paid'));
const status=(i:any)=>i.status==='unpaid'&&i.due_date<page.props.today?'Overdue':i.status.replaceAll('_',' ');
const rank=(i:any)=>status(i)==='Overdue'?0:i.status==='unpaid'?1:i.kind==='income'?2:3;
const dayItems=(value:string)=>visibleItems.value.filter(i=>i.due_date===value).sort((a,b)=>rank(a)-rank(b)||a.slot_order-b.slot_order);
const hiddenCount=(value:string)=>items.value.filter(i=>i.due_date===value&&i.kind!=='income'&&i.status==='paid').length;
const weekItems=(start:string)=>visibleItems.value.filter(i=>i.due_date>=start&&i.due_date<=iso(new Date(new Date(start+'T12:00:00Z').getTime()+6*86400000))).sort((a,b)=>a.due_date.localeCompare(b.due_date)||rank(a)-rank(b));
const daySummary=computed(()=>{const rows=items.value.filter(i=>i.due_date===day.value);const payments=rows.filter(i=>i.kind!=='income');return {income:rows.filter(i=>i.kind==='income').reduce((sum,i)=>sum+Number(i.amount_cents||0),0),due:payments.reduce((sum,i)=>sum+Number(i.amount_cents||0),0),paid:payments.filter(i=>i.status==='paid').reduce((sum,i)=>sum+Number(i.amount_cents||0),0),unpaid:payments.filter(i=>i.status!=='paid').reduce((sum,i)=>sum+Number(i.amount_cents||0),0),unknown:rows.filter(i=>i.amount_cents===null).length};});
const usage=(accounts:any[])=>accounts.every(a=>a.balance_cents!==null&&Number(a.limit_cents)>0)?(Math.max(0,accounts.reduce((n,a)=>n+Number(a.balance_cents),0))/accounts.reduce((n,a)=>n+Number(a.limit_cents),0)*100).toFixed(1)+'%':'Usage unavailable';
const progress=(accounts:any[])=>{const scheduled=accounts.filter(a=>a.loan?.series_id&&a.loan?.repayment_total_cents!==null&&a.loan?.repayment_total_cents!==undefined);const total=scheduled.reduce((n,a)=>n+Number(a.loan.repayment_total_cents),0),paid=scheduled.reduce((n,a)=>n+Number(a.loan.paid_cents),0);return scheduled.length?money(paid)+' of '+money(total)+' repaid ('+(total?paid/total*100:100).toFixed(1)+'%) · scheduled loans':'Balance tracking';};
const groups=computed(()=>[{title:'Cash',types:['cash','checking','savings']},{title:'Investments',types:['investment']},{title:'Credit cards',types:['credit_card']},{title:'Loans',types:['loan']}].map(g=>({...g,accounts:items.value.filter(a=>g.types.includes(a.type))})));
const budgetTotals=computed(()=>({spent:items.value.reduce((sum,r)=>sum+Number(r.spent_cents),0),target:items.value.reduce((sum,r)=>sum+Number(r.target_cents||0),0),remaining:items.value.reduce((sum,r)=>sum+Number(r.remaining_cents||0),0),over:items.value.reduce((sum,r)=>sum+Number(r.over_cents||0),0)}));
const selectedBudget=computed(()=>items.value.find(r=>r.id===props.selectedCategory));
const subscriptionEstimate=computed(()=>items.value.filter(s=>!s.cancel_date||s.cancel_date>page.props.today).reduce((sum,s)=>sum+Number(s.amount_cents||0)*({once:0,weekly:52/12,biweekly:26/12,monthly:1,twice_monthly:2,yearly:1/12} as any)[s.frequency],0));
const accountName=(id:string)=>props.catalog.accounts.find((a:any)=>a.id===id)?.name||'Deleted account';
const categoryName=(id:string)=>{const c=props.catalog.categories.find((c:any)=>c.id===id);return c?(c.parent_id?(props.catalog.categories.find((p:any)=>p.id===c.parent_id)?.name||'Category')+' › ':'')+c.name:'Uncategorized';};
const memberName=(id:string)=>props.catalog.members.find((m:any)=>m.id===id)?.nickname||'Shared';
function create(kind?:string){editor.value={kind:kind||({home:'schedule',bills:'schedule',income:'schedule',subscriptions:'schedule',accounts:'account',loans:'loan',transactions:'transaction',categories:'category',household:'member',budget:'target'} as any)[props.section],record:props.section==='subscriptions'?{kind:'subscription'}:props.section==='bills'?{kind:'bill'}:props.section==='income'?{kind:'income'}:undefined};}
function edit(kind:string,record:any,extra:any={}){editor.value={kind,record,...extra};}
function remove(endpoint:string,record:any,extra:any={}){editor.value={kind:'delete',record,endpoint,...extra};}
function visitMonth(amount:number){router.get('/'+props.section,{month:shiftMonth(props.month||page.props.utcMonth,amount),...(props.section==='home'?{assignment:assignmentFilter.value}: {})},{preserveState:props.section==='home',preserveScroll:true});}
function filter(){
 const assignment={assignment:assignmentFilter.value};
 const pagination={per_page:props.records?.per_page||25};
 const data=props.section==='home'?{month:props.month||page.props.utcMonth,...assignment}:props.section==='loans'?{show_paid:showPaidLoans.value?1:0,...assignment,...pagination}:{search:search.value,account:accountFilter.value,category:categoryFilter.value,show_canceled:showCanceled.value?1:0,show_hidden:showHidden.value?1:0,...(['bills','income','subscriptions'].includes(props.section)?{...assignment,...pagination}:{})};
 router.get('/'+props.section,data,{preserveState:true,preserveScroll:true});
}
async function showHistory(type:string,id:string){try{drawer.value={title:'Change history',history:await json('/history/'+type+'/'+id)};}catch(e:any){loadingError.value=e.message;}}
async function drawerPage(url:string){try{if(drawer.value)drawer.value.data=await json(url);}catch(e:any){loadingError.value=e.message;}}
async function details(kind:string,record:any){if(kind==='accounts'){router.visit('/accounts/'+record.id);return;}try{drawer.value={title:record.name||record.account?.name,kind,record,data:await json('/'+kind+'/'+record.id)};}catch(e:any){loadingError.value=e.message;}}
function mutate(url:string,data:any={},method:'post'|'delete'='post'){router.visit(url,{method,data:{command_key:crypto.randomUUID(),...data},preserveScroll:true,onError:e=>loadingError.value=Object.values(e).join(' '),onHttpException:r=>{loadingError.value=r.status===409?'This record changed. Reload before trying again.':'The change could not be saved.';return false;}});}
function leave(){editor.value={kind:'leave',record:{name:page.props.household.name}};}
watch(()=>props.section,()=>{editor.value=null;occurrence.value=undefined;drawer.value=null;day.value=undefined;loadingError.value='';});
function scheduleEdit(detail:any){edit('schedule',detail.series,{series:detail.series,occurrence:detail.occurrence});occurrence.value=undefined;}
function scheduleRemove(detail:any){remove('/schedules/'+detail.series.id,detail.series,{occurrence:detail.occurrence});occurrence.value=undefined;}
function editSeries(record:any){if(!record.next&&!record.anchor){loadingError.value='No live occurrence is available to edit. Add a new schedule.';return;}edit('schedule',record,{occurrence:record.next||record.anchor});}
function addPayment(kind:string){editor.value={kind:'schedule',record:{kind}};}
function clearFilters(){search.value='';accountFilter.value='';categoryFilter.value='';assignmentFilter.value='';showCanceled.value=false;showPaidLoans.value=false;showHidden.value=false;filter();}
function accountEdit(kind:string,record:any){if(kind==='account'&&record.type==='loan'){router.visit('/loans');return;}accountDetail.value=undefined;edit(kind,record);}
watch(()=>page.url,()=>{const value=new URL(page.url,window.location.origin).searchParams.get('occurrence');if(props.section==='home'&&value)occurrence.value=value;},{immediate:true});
function openNotification(n:any){router.post('/notifications/'+n.id+'/read',{}, {onSuccess:()=>{if(n.data.destination)router.visit(n.data.destination);}});}
</script>
<template><AppLayout :section="section"><Head :title="title[section]"/>
 <div v-if="section!=='home'" class="page-header"><div class="flex flex-wrap items-center gap-4"><h1>{{title[section]}}</h1><div v-if="section==='budget'" class="flex items-center gap-2"><button class="icon-btn border border-control bg-white" aria-label="Previous month" @click="visitMonth(-1)"><ChevronLeft :size="16"/></button><span class="font-medium">{{monthLabel(month||page.props.utcMonth)}}</span><button class="icon-btn border border-control bg-white" aria-label="Next month" @click="visitMonth(1)"><ChevronRight :size="16"/></button><span v-if="month===page.props.utcMonth" class="badge badge-info">Current month</span><button v-else class="btn text-xs!" @click="router.get('/budget',{month:page.props.utcMonth})">Back to {{monthLabel(page.props.utcMonth)}}</button></div></div>
  <button v-if="['bills','income'].includes(section)" class="btn-primary" @click="addPayment(section==='income'?'income':'bill')"><Plus :size="16"/>{{section==='income'?'New income':'New bill'}}</button>
  <button v-if="['budget','subscriptions','loans','transactions','categories'].includes(section)&&(section!=='budget'||(month||page.props.utcMonth)>=page.props.utcMonth)" class="btn-primary" @click="create()"><Plus :size="16"/>{{section==='budget'?'Add target':section==='loans'?'Add loan':section==='transactions'?'Add manual transaction':section==='categories'?'Add category':'New subscription'}}</button>
  <div v-if="section==='accounts'" class="flex items-center gap-3"><Link href="/household" class="text-xs text-income hover:underline">Manage connections</Link><div class="relative"><button class="btn" :aria-expanded="addAccountMenu" @click="addAccountMenu=!addAccountMenu"><Plus :size="16"/>Add manual account</button><div v-if="addAccountMenu" class="absolute right-0 z-30 mt-2 w-56 rounded-lg border border-line bg-white p-2 shadow-lg"><button v-for="[value,label] in [['cash','Cash'],['checking','Checking'],['savings','Savings'],['credit_card','Credit card']]" :key="value" class="block w-full rounded px-3 py-2 text-left hover:bg-ground" @click="editor={kind:'account',record:{type:value}};addAccountMenu=false">{{label}}</button><Link href="/loans" class="block rounded px-3 py-2 hover:bg-ground">Loan · add from Loans</Link></div></div><Link v-if="providerReady" href="/connections/authorize" class="btn-primary">Connect a bank</Link></div>
  <button v-if="section==='notifications'" class="btn" @click="mutate('/notifications/read')">Mark all as read</button>
 </div>
 <p v-if="loadingError" role="alert" class="mb-6 rounded-md border border-orange-200 bg-orange-50 p-3 text-orange-800">{{loadingError}}<button class="ml-4 underline" @click="loadingError='';router.reload()">Reload</button></p>
 <div v-if="section==='home'" class="page-header"><div class="flex items-center gap-2"><h1 class="mr-2">{{monthLabel(month||page.props.utcMonth)}}</h1><button class="btn size-10 px-0!" aria-label="Previous month" @click="visitMonth(-1)"><ChevronLeft :size="18"/></button><button class="btn size-10 px-0!" aria-label="Next month" @click="visitMonth(1)"><ChevronRight :size="18"/></button><button class="btn ml-1" @click="router.get('/home',{month:page.props.utcMonth,assignment:assignmentFilter},{preserveState:true,preserveScroll:true})">Today</button></div></div>
 <div v-if="section==='home'" class="mb-5 flex flex-wrap items-center gap-3"><AssignmentFilter v-model="assignmentFilter" :members="catalog.members" @change="filter"/><button v-if="assignmentFilter" class="btn" @click="clearFilters">Clear filters</button></div>
 <template v-if="section==='home'">
  <div v-if="setup" class="panel mb-6 p-5"><div class="flex justify-between"><h2 class="text-base">Set up your household</h2><button class="help underline" @click="mutate('/home/setup/dismiss')">Hide checklist</button></div><p class="help mt-2">{{Object.values(setup).filter(Boolean).length}} of 3 complete · Shared by all household members.</p><div class="mt-4 flex flex-wrap gap-3"><Link href="/household" class="btn">{{setup.accounts?'✓':'1.'}} Connect a bank or add an account</Link><Link href="/bills" class="btn">{{setup.bills?'✓':'2.'}} Add bills</Link><Link href="/household" class="btn">{{setup.members?'✓':'3.'}} Invite or add a member</Link></div></div>
  <div class="mb-6 grid grid-cols-2 gap-4 xl:grid-cols-4"><div v-for="[label,key,color] in [['Expected income','income_cents','text-income'],['Total due','due_cents',''],['Paid','paid_cents',''],['Unpaid','unpaid_cents','']]" class="panel px-5 py-4"><p class="text-xs text-muted">{{label}}</p><p class="mt-2 text-2xl font-semibold tabular-nums" :class="color">{{money(summary?.[key])}}</p><p class="help mt-2">{{key==='income_cents'?items.filter(i=>i.kind==='income'&&i.due_date.startsWith(month||'')).length+' scheduled payments':key==='due_cents'?items.filter(i=>i.kind!=='income'&&i.due_date.startsWith(month||'')).length+' bills, loans and subscriptions':key==='paid_cents'?items.filter(i=>i.kind!=='income'&&i.status==='paid'&&i.due_date.startsWith(month||'')).length+' paid this month':items.filter(i=>i.kind!=='income'&&i.status==='unpaid'&&i.due_date.startsWith(month||'')).length+' still to pay this month'}}</p><p v-if="key==='due_cents'&&summary?.unknown_count" class="help mt-1">Known subtotal · {{summary.unknown_count}} unknown amounts</p></div></div>
  <div v-if="!listView" class="panel overflow-x-auto"><div class="min-w-195"><div class="grid grid-cols-[repeat(7,minmax(0,1fr))_130px] border-b border-line bg-zinc-50"><div v-for="d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun','Week total']" class="px-3 py-3 text-xs font-medium text-muted">{{d}}</div></div>
   <div v-for="(week,weekIndex) in weeks" :key="week.start" class="grid grid-cols-[repeat(7,minmax(0,1fr))_130px]"><div v-for="value in days.slice(weekIndex*7,weekIndex*7+7)" :key="value" class="min-h-36 border-b border-r border-line p-2" :class="!value.startsWith(month||'')?'bg-zinc-50/60':''">
    <button class="mb-2 flex size-6 items-center justify-center rounded-full text-xs" :class="value===page.props.today?'bg-ink text-white':!value.startsWith(month||'')?'text-zinc-400':'text-muted'" :aria-label="'Payments for '+dateLabel(value)" @click="day=value">{{Number(value.slice(8))}}</button>
    <button v-for="item in dayItems(value).slice(0,3)" :key="item.id" class="mb-1 flex w-full flex-col rounded-sm px-1.5 py-1 text-left text-[11px] leading-tight" :class="status(item)==='Overdue'?'bg-warning-soft text-warning':item.kind==='income'?'bg-info-soft text-income':['paid','received'].includes(item.status)?'border border-line text-muted':'bg-ground text-ink-secondary'" @click="occurrence=item.id"><span class="flex w-full items-center justify-between gap-1"><span class="truncate font-medium" :class="['paid','received'].includes(item.status)?'line-through':''">{{item.name}}</span><span class="shrink-0 tabular-nums">{{item.amount_cents===null?'—':money(item.amount_cents)}}</span></span><span v-if="status(item)==='Overdue'" class="mt-1 text-[10px] font-semibold uppercase">Overdue</span></button>
    <p v-if="hidePaid&&hiddenCount(value)" class="mb-1 px-1 text-[10px] text-muted">{{hiddenCount(value)}} paid hidden</p>
    <button v-if="dayItems(value).length>3" class="px-1 text-[11px] text-muted underline" @click="day=value">+{{dayItems(value).length-3}} more</button>
   </div><div class="border-b border-line bg-subtle p-3 text-xs"><div v-for="[label,key] in [['Due','due_cents'],['Paid','paid_cents'],['Unpaid','unpaid_cents'],['Income','income_cents']]" :key="key" class="mb-1.5 flex justify-between gap-2"><span class="text-muted">{{label}}</span><span class="money" :class="key==='income_cents'?'text-income':''">{{money(week[key])}}</span></div><p v-if="week.unknown_count" class="help mt-1">{{week.unknown_count}} unknown</p></div></div>
  </div></div>
  <div v-else class="panel overflow-x-auto"><table><thead><tr><th>Due date</th><th>Payment</th><th>Category</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr v-for="item in visibleItems" :key="item.id" class="hover:bg-zinc-50"><td>{{dateLabel(item.due_date)}}</td><td><button class="font-medium hover:underline" @click="occurrence=item.id">{{item.name}}</button></td><td class="text-muted">{{categoryName(item.category_id)}}</td><td class="money" :class="item.kind==='income'?'text-income':''">{{money(item.amount_cents)}}</td><td><span class="badge">{{status(item)}}</span></td></tr></tbody></table><div v-if="!visibleItems.length" class="empty"><CalendarDays :size="30"/><p>No payments in this view.</p><button class="btn" @click="create()">Add your first payment</button></div></div>
  <div v-if="!listView" class="mt-4 flex flex-wrap items-center justify-between gap-3 text-[11px] text-muted"><div class="flex gap-4"><span><span class="mr-1 inline-block size-3 rounded-sm border border-line bg-ground"/>Bill, loan or subscription</span><span><span class="mr-1 inline-block size-3 rounded-sm border border-blue-200 bg-info-soft"/>Income</span><span><span class="mr-1 inline-block size-3 rounded-sm border border-orange-200 bg-warning-soft"/>Overdue</span><span><span class="mr-1 inline-block size-3 rounded-sm border border-line bg-white"/>Paid</span></div><span>Totals always include paid bills, even when hidden.</span></div>
  <div v-if="!listView" class="mt-7 space-y-3"><div class="flex items-center justify-between gap-4"><h2>Items by week</h2><label class="flex items-center gap-2 whitespace-nowrap text-xs font-normal text-muted"><input :checked="!hidePaid" type="checkbox" @change="hidePaid=!($event.target as HTMLInputElement).checked"/>Show paid bills</label></div><section v-for="week in weeks" :key="week.start" class="panel overflow-hidden"><div class="flex flex-wrap items-center justify-between gap-2 border-b border-line bg-subtle px-4 py-3"><h3 class="font-medium">Week of {{dateLabel(week.start)}}</h3><p class="help">Due {{money(week.due_cents)}} · Paid {{money(week.paid_cents)}} · Unpaid {{money(week.unpaid_cents)}} · <span class="text-income">Income {{money(week.income_cents)}}</span></p></div><button v-for="item in weekItems(week.start)" :key="item.id" class="grid w-full grid-cols-[130px_1fr_auto_100px] items-center gap-3 border-b border-line-soft px-4 py-3 text-left hover:bg-ground" @click="occurrence=item.id"><span class="text-xs">{{dateLabel(item.due_date)}}</span><span><span class="block font-medium">{{item.name}}</span><span class="help mt-0.5 block">{{item.kind.replaceAll('_',' ')}}</span></span><span class="badge" :class="status(item)==='Overdue'?'badge-warning':item.kind==='income'?'badge-info':''">{{status(item)}}</span><span class="money text-right" :class="item.kind==='income'?'text-income':''">{{money(item.amount_cents)}}</span></button><p v-if="!weekItems(week.start).length" class="help px-4 py-3">No visible items this week.</p></section></div>
  <p class="help mt-4">Monthly totals use due dates in {{monthLabel(month||page.props.utcMonth)}}. Weeks include all seven days. Show paid bills does not change totals; income remains visible after receipt.</p>
 </template>
 <template v-else-if="section==='budget'">
  <p v-if="(month||page.props.utcMonth)<page.props.utcMonth" class="callout mb-5">Past-month targets are locked. Spending still reflects transaction corrections.</p><p v-else-if="(month||page.props.utcMonth)>page.props.utcMonth" class="callout mb-5">Targets repeat from month to month. Unused amounts and overspending don’t carry over.</p>
  <div class="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4"><div v-for="[label,value,color] in [['Spent',budgetTotals.spent,''],['Targets',budgetTotals.target,''],['Remaining in targeted categories',budgetTotals.remaining,''],['Over target',budgetTotals.over,'text-warning']]" class="panel px-4 py-4"><p class="help">{{label}}</p><p class="mt-2 text-2xl font-semibold tabular-nums" :class="String(color)">{{money(Number(value))}}</p><p class="help mt-2">{{label==='Spent'?'All expense categories and Uncategorized':label==='Targets'?'Monthly targets · USD':label==='Remaining in targeted categories'?'Targets minus their spending':'Targets are informational'}}</p></div></div>
  <div class="grid items-start gap-5" :class="contributions?'xl:grid-cols-[minmax(0,1fr)_320px]':''"><section class="panel overflow-x-auto"><div class="flex items-center justify-between gap-2 px-4 py-4"><h2>Spending by category</h2><span class="help">Select a category to see its transactions</span></div><table><thead><tr><th>Category</th><th class="text-right!">Spent</th><th class="text-right!">Target</th><th class="text-right!">Remaining</th><th class="text-right!">Over target</th></tr></thead><tbody><tr v-for="row in items" :key="row.id" :class="selectedCategory===row.id?'selected-row':''"><td class="min-w-40"><Link :href="'/budget?month='+month+'&category='+row.id" class="font-medium hover:underline">{{row.name}}</Link><p class="help mt-1">{{row.count}} transactions</p><div v-if="row.target_cents!==null" class="mt-2 h-1 w-full rounded-full bg-ground"><div class="h-1 rounded-full" :class="Number(row.over_cents)>0?'bg-warning-strong':'bg-ink'" :style="{width:Math.max(0,Math.min(100,Number(row.spent_cents)/Math.max(1,Number(row.target_cents))*100))+'%'}"/></div></td><td class="money text-right">{{money(row.spent_cents)}}</td><td class="money text-right">{{row.target_cents===null?'No target':money(row.target_cents)}}</td><td class="money text-right">{{row.target_cents===null?'—':money(row.remaining_cents)}}</td><td class="text-right"><span v-if="Number(row.over_cents)>0" class="badge badge-warning">Over by {{money(row.over_cents)}}</span><span v-else class="money">{{row.target_cents===null?'—':'$0.00'}}</span></td></tr><tr v-if="items.length" class="bg-subtle font-semibold"><td>Total</td><td class="money text-right">{{money(budgetTotals.spent)}}</td><td class="money text-right">{{money(budgetTotals.target)}}</td><td class="money text-right">{{money(budgetTotals.remaining)}}</td><td class="money text-right">{{money(budgetTotals.over)}}</td></tr></tbody></table><div v-if="!items.length" class="empty"><Wallet :size="26"/><p class="font-medium text-ink">No spending or targets this month</p><p class="help">Add an expense target or record a transaction to start your Budget.</p><button v-if="(month||page.props.utcMonth)>=page.props.utcMonth" class="btn-primary" @click="create()">Add target</button></div><p class="help border-t border-line px-4 py-4">Includes pending and posted transactions in this UTC month. Refunds reduce spending. Transfers, card repayments and investment trades are excluded. Schedules and attachments never count twice.</p></section>
  <aside v-if="contributions" class="panel min-w-0 overflow-hidden"><div v-if="selectedBudget" class="border-b border-line p-4"><div class="flex items-center justify-between"><h2>{{selectedBudget.name}}</h2><Link :href="'/budget?month='+month" class="icon-btn" aria-label="Close contributions"><X :size="16"/></Link></div><p class="help mt-1">{{monthLabel(month||page.props.utcMonth)}} · {{selectedBudget.count}} transactions</p><div class="mt-4 grid grid-cols-3 gap-2"><div v-for="[label,value] in [['Spent',money(selectedBudget.spent_cents)],['Target',selectedBudget.target_cents===null?'No target':money(selectedBudget.target_cents)],['Remaining',money(selectedBudget.remaining_cents)]]"><p class="help">{{label}}</p><p class="money mt-1">{{value}}</p></div></div><p v-if="Number(selectedBudget.over_cents)>0" class="mt-4 rounded-md bg-warning-soft p-3 text-xs text-warning">Over by {{money(selectedBudget.over_cents)}}. {{selectedBudget.alerted?'The household has already received its alert for this month.':'Targets are informational.'}}</p><button v-if="selectedBudget.id!=='uncategorized'&&!selectedBudget.name.includes('(deleted)')&&(month||page.props.utcMonth)>=page.props.utcMonth" class="btn mt-4 text-xs!" @click="edit('target',{...selectedBudget,category_id:selectedBudget.id})">{{selectedBudget.target_cents===null?'Set a target':'Edit target'}}</button></div><div v-if="breakdown?.length" class="border-b border-line p-4"><p class="preview-caption">By subcategory</p><div v-for="row in breakdown" :key="row.id" class="flex justify-between py-1 text-xs"><span>{{row.name}}</span><span class="money">{{money(row.spent_cents)}}</span></div></div><div v-for="t in contributions.data" :key="t.id" class="border-b border-line-soft p-4"><button class="text-left font-medium hover:underline" @click="transactionDetail=t.id">{{t.payee}}</button><span v-if="t.status==='pending'" class="badge badge-pending ml-2">Pending</span><span v-if="Number(t.amount_cents)>0" class="badge badge-info ml-2">Refund</span><div class="mt-2 flex justify-between gap-2"><p class="help">{{dateLabel(t.transaction_date)}} · {{accountName(t.account_id)}}</p><span class="money text-xs">{{money(t.amount_cents)}}</span></div></div><Pagination :records="contributions"/><div class="border-t border-line p-4"><Link :href="'/transactions?category='+selectedCategory" class="text-xs text-income underline">Open in Transactions</Link></div></aside></div>
 </template>
 <template v-else-if="section==='accounts'">
  <BalanceChart :accounts="items" :history="history" :limits="limits||[]" :today="page.props.today" :summary="summary" class="mb-5"/>
  <section v-for="group in groups.filter(g=>g.accounts.length)" :key="group.title" class="panel mb-4 overflow-hidden"><div class="flex items-center justify-between border-b border-line bg-subtle px-4 py-3"><div class="flex items-center gap-2"><h2>{{group.title}}</h2><span class="help">{{group.accounts.length}} accounts</span></div><div class="text-right"><p class="money">{{money(group.accounts.reduce((n,a)=>n+Number(a.balance_cents||0),0))}}{{group.types.includes('credit_card')||group.types.includes('loan')?' owed':''}}</p><p v-if="group.accounts.some(a=>a.balance_cents===null)" class="help">Known subtotal</p><p v-if="group.types.includes('credit_card')" class="help">{{usage(group.accounts)}}</p></div></div><div v-for="a in group.accounts" :key="a.id" class="flex items-center justify-between gap-4 border-b border-line-soft px-4 py-3 last:border-0"><div class="min-w-0"><button class="font-medium hover:underline" @click="details('accounts',a)">{{a.name}}</button><p class="help mt-1">{{a.institution_name||a.type.replaceAll('_',' ')}} · {{a.source==='manual'?'Manual':'Connected'}} · {{memberName(a.member_id)}}<span v-if="a.balance_date"> · {{dateLabel(a.balance_date)}}</span></p><template v-if="a.type==='credit_card'"><p class="help mt-1">{{a.limit_cents===null?'Credit limit unavailable':usage([a])+' of '+money(a.limit_cents)+' limit'}}</p><div v-if="Number(a.limit_cents)>0" class="mt-1.5 h-1 w-56 rounded-full bg-ground"><div class="h-1 rounded-full bg-income" :style="{width:Math.max(0,Math.min(100,Number(a.balance_cents)/Number(a.limit_cents)*100))+'%'}"/></div></template><template v-if="a.type==='loan'&&a.loan?.series_id"><p class="help mt-1">{{progress([a])}}</p><div class="mt-1.5 h-1 w-56 rounded-full bg-ground"><div class="h-1 rounded-full bg-income" :style="{width:Math.min(100,Number(a.loan.paid_cents)/Math.max(1,Number(a.loan.repayment_total_cents))*100)+'%'}"/></div></template><p v-if="a.latest_error" class="help mt-1 text-warning">Latest sync failed. Open account details to review its connection.</p></div><div class="flex shrink-0 items-center gap-4"><span class="money">{{money(a.balance_cents)}}{{['credit_card','loan'].includes(a.type)?' owed':''}}</span><button v-if="a.source==='manual'&&a.type!=='loan'" class="btn min-h-8! text-xs!" @click="edit('balance',a)">Update balance</button><button v-else-if="a.type==='loan'" class="btn min-h-8! text-xs!" @click="router.visit('/loans'+(a.loan?.id?'?loan='+a.loan.id+'&show_paid=1':''))">Open loan</button></div></div></section><div v-if="!items.length" class="panel empty"><Landmark :size="28"/><p class="font-medium text-ink">No accounts yet</p><p class="help max-w-sm">Connect a bank to import balances and transactions, or add a cash or other account by hand.</p><div class="flex gap-2"><Link href="/household" class="btn-primary">Connect a bank</Link><button class="btn" @click="create()">Add manual account</button></div></div>
 </template>
 <template v-else-if="['bills','income','subscriptions'].includes(section)">
  <div class="mb-5 flex flex-wrap items-center justify-between gap-3"><label v-if="section==='subscriptions'" class="flex items-center gap-2 font-normal text-muted"><input v-model="showCanceled" type="checkbox" @change="filter"/>Show canceled</label><div class="flex flex-wrap items-center gap-3"><AssignmentFilter v-model="assignmentFilter" :members="catalog.members" @change="filter"/><form class="relative w-64" @submit.prevent="filter"><Search class="absolute left-3 top-3 text-muted" :size="16"/><input v-model="search" :aria-label="section==='income'?'Search income':section==='bills'?'Search bills':'Search subscriptions'" class="pl-9!" placeholder="Search"/></form><button v-if="search||assignmentFilter||(section==='subscriptions'&&showCanceled)" class="btn" @click="clearFilters">Clear filters</button></div></div>
  <SubscriptionWorkspace v-if="section==='subscriptions'" :records="records" :summary="summary" :catalog="catalog" :today="page.props.today" @edit="editSeries" @cancel="s=>edit('cancel',s)" @remove="s=>remove('/schedules/'+s.id,s)" @payment="id=>occurrence=id" @history="s=>showHistory('scheduled_series',s.id)"/>
  <div v-else class="panel overflow-x-auto"><table><thead><tr><th>Name</th><th>Schedule</th><th>{{section==='income'?'Next expected':'Next due'}}</th><th class="text-right!">Amount</th><th>Assigned</th><th/></tr></thead><tbody><tr v-for="s in items" :key="s.id"><td><button class="font-medium hover:underline" @click="editSeries(s)">{{s.name}}</button><p v-if="s.generated_by_account_id" class="help mt-1">Generated card payment</p></td><td class="text-muted">{{s.frequency.replaceAll('_',' ')}}<p class="help mt-1">{{categoryName(s.category_id)}}</p></td><td><button v-if="s.next" class="hover:underline" @click="occurrence=s.next.id">{{dateLabel(s.next.due_date)}}<span v-if="status(s.next)==='Overdue'" class="badge badge-warning ml-2">Overdue</span></button><span v-else class="text-muted">Complete</span></td><td class="money text-right" :class="s.kind==='income'?'text-income':''">{{s.kind==='income'?'+':''}}{{money(s.next?s.next.amount_cents:s.amount_cents)}}</td><td class="text-muted">{{memberName(s.member_id)}}</td><td><button class="icon-btn" aria-label="Schedule history" @click="showHistory('scheduled_series',s.id)"><History :size="15"/></button></td></tr></tbody></table><div v-if="!items.length" class="empty"><ReceiptText :size="28"/><p class="font-medium text-ink">{{search||assignmentFilter||(section==='subscriptions'&&showCanceled)?(section==='income'?'No income matches':'No bills match'):(section==='income'?'No income yet':'No bills yet')}}</p><p class="help">{{section==='income'?'Add paychecks or other expected income to see it on Home.':'Add rent, utilities or other bills to see them on Home.'}}</p><button v-if="search||assignmentFilter||(section==='subscriptions'&&showCanceled)" class="btn" @click="clearFilters">Clear filters</button><button v-else class="btn-primary" @click="addPayment(section==='income'?'income':'bill')">{{section==='income'?'New income':'New bill'}}</button></div><Pagination :records="records"/></div>
 </template>
 <template v-else-if="section==='transactions'">
  <div class="mb-5 flex flex-wrap items-center gap-3"><form class="relative w-64" @submit.prevent="filter"><Search class="absolute left-3 top-3 text-muted" :size="16"/><input v-model="search" aria-label="Search transactions" class="pl-9!" placeholder="Search payees"/></form><SelectField v-model="accountFilter" class="w-44!" aria-label="Filter by account" @change="filter" searchable :options="[{value:'',label:'All accounts'},...(catalog.accounts).map((a:any)=>({value:a.id,label:a.name}))]"/><SelectField v-model="categoryFilter" class="w-60!" aria-label="Filter by category" @change="filter" searchable :options="[{value:'',label:'All categories'},{value:'uncategorized',label:'Uncategorized'},...(catalog.categories).map((c:any)=>({value:c.id,label:categoryName(c.id)}))]"/><label class="flex items-center gap-2 font-normal text-muted"><input v-model="showHidden" type="checkbox" @change="filter"/>Show hidden</label></div>
  <div class="grid items-start gap-5" :class="selectedTransaction?'xl:grid-cols-[minmax(0,1fr)_340px]':''"><div class="panel min-w-0 overflow-x-auto"><table><thead><tr><th>Date</th><th>Payee</th><th>Category</th><th class="text-right!">Amount</th></tr></thead><tbody><tr v-for="t in items" :key="t.id" :class="[t.hidden?'opacity-50':'',selectedTransaction===t.id?'selected-row':'']"><td class="text-xs text-muted">{{dateLabel(t.transaction_date)}}</td><td><button class="text-left font-medium hover:underline" @click="transactionPanel?transactionPanel.selectTransaction(t.id):selectedTransaction=t.id">{{t.payee}}</button><span v-if="t.status==='pending'" class="badge badge-pending ml-2">Pending</span><p class="help mt-1">{{accountName(t.account_id)}}{{t.source==='manual'?' · Manual':''}}</p></td><td class="text-xs text-muted">{{categoryName(t.category_id)}}</td><td class="money text-right" :class="Number(t.amount_cents)>0?'text-income':''">{{Number(t.amount_cents)>0?'+':''}}{{money(t.amount_cents)}}</td></tr></tbody></table><div v-if="!items.length" class="empty"><ReceiptText :size="28"/><p class="font-medium text-ink">{{search||accountFilter||categoryFilter?'No transactions match':'No transactions yet'}}</p><p class="help">Transactions arrive from connected banks. You can also add them to manual accounts.</p><button v-if="search||accountFilter||categoryFilter" class="btn" @click="clearFilters">Clear filters</button><button v-else class="btn" @click="create()">Add manual transaction</button></div><Pagination :records="records"/></div>
  <TransactionDetails v-if="selectedTransaction" :version="items.find(t=>t.id===selectedTransaction)?.lock_version" ref="transactionPanel" @select="id=>selectedTransaction=id" embedded :id="selectedTransaction" :catalog="catalog" @close="selectedTransaction=undefined" @edit="record=>edit('transaction',record)" @remove="record=>remove('/transactions/'+record.id,record)" @history="id=>showHistory('transactions',id)" @payment="id=>occurrence=id"/>
  </div>
 </template>
 <template v-else-if="section==='loans'">
  <div class="mb-5 flex flex-wrap items-center gap-3"><AssignmentFilter v-model="assignmentFilter" :members="catalog.members" @change="filter"/><label class="flex items-center gap-2 font-normal text-muted"><input v-model="showPaidLoans" type="checkbox" @change="filter"/>Show paid-off loans</label><button v-if="assignmentFilter||showPaidLoans" class="btn" @click="clearFilters">Clear filters</button></div>
  <LoanWorkspace :records="records" :today="page.props.today" @edit="record=>edit('loan',record)" @extra="record=>edit('payment',record)" @history="record=>showHistory('loans',record.id)" @remove="record=>remove('/loans/'+record.id,record)" @payment="id=>occurrence=id" @correct="record=>edit('payment',record,{endpoint:'/loan-payments/'+record.id})" @remove-payment="record=>remove('/loan-payments/'+record.id,record)"/>
 </template>
 <template v-else-if="section==='categories'">
  <div class="mb-5 flex items-center justify-between gap-3"><div class="segmented"><button v-for="[value,label] in [['expense','Expenses'],['income','Income'],['transfer','Transfers']]" :key="value"  :aria-pressed="categoryTab===value" @click="categoryTab=value">{{label}} · {{items.filter(c=>c.kind===value&&!c.parent_id).length}}</button></div><div class="flex gap-2"><button class="btn min-h-8! text-xs!" @click="collapsedCategories=[]">Expand all</button><button class="btn min-h-8! text-xs!" @click="collapsedCategories=items.filter(c=>!c.parent_id).map(c=>c.id)">Collapse all</button></div></div>
  <div class="panel overflow-x-auto"><table><thead><tr><th>Category</th><th>Usage</th><th>Monthly target</th><th/></tr></thead><tbody><template v-for="c in items.filter(c=>c.kind===categoryTab&&!c.parent_id)" :key="c.id"><tr><td class="font-medium"><button :aria-expanded="!collapsedCategories.includes(c.id)" @click="toggleCategory(c.id)"><ChevronRight :size="12" class="mr-1 inline" :class="!collapsedCategories.includes(c.id)?'rotate-90':''"/>{{c.name}}</button><span v-if="c.system_key" class="badge ml-2">Built-in</span><p class="help mt-1">{{c.child_count}} subcategories</p></td><td class="text-muted">{{c.transaction_count}} transactions · {{c.schedule_count}} schedules</td><td>{{c.target_cents===null?'No target':money(c.target_cents)}}</td><td><div class="flex justify-end gap-1"><button v-if="c.system_key!=='transfers'" class="btn py-1.5!" @click="edit('category',{kind:c.kind,parent_id:c.id})"><Plus :size="14"/>Subcategory</button><button v-if="!c.system_key" class="icon-btn" aria-label="Edit category" @click="edit('category',c)"><Pencil :size="15"/></button><button v-if="!c.system_key" class="icon-btn" aria-label="Delete category" @click="remove('/categories/'+c.id,c)"><Trash2 :size="15"/></button></div></td></tr><tr v-for="child in items.filter(child=>child.parent_id===c.id&&!collapsedCategories.includes(c.id))" :key="child.id" class="bg-zinc-50/50"><td class="pl-9! text-muted">{{categoryName(child.id)}}</td><td class="text-muted">{{child.transaction_count}} transactions · {{child.schedule_count}} schedules</td><td class="help">Included in parent</td><td><div class="flex justify-end"><button class="icon-btn" aria-label="Edit subcategory" @click="edit('category',child)"><Pencil :size="15"/></button><button class="icon-btn" aria-label="Delete subcategory" @click="remove('/categories/'+child.id,child)"><Trash2 :size="15"/></button></div></td></tr></template></tbody></table></div>
 </template>
 <template v-else-if="section==='household'"><div class="max-w-4xl space-y-5">
  <HouseholdName :household="page.props.household"/>
  <section class="panel"><div class="flex items-center justify-between px-5 py-4"><h2>Members</h2><div v-if="page.props.household.owner" class="flex gap-2"><button class="btn min-h-9! text-xs!" @click="create('invitation')">Invite with Google</button><button class="btn-primary min-h-9! text-xs!" @click="create('member')">Add member</button></div></div><div v-for="m in items" :key="m.id" class="flex items-center justify-between gap-3 border-t border-line-soft px-5 py-3"><div class="flex items-center gap-3"><span class="avatar">{{m.nickname.slice(0,2).toUpperCase()}}</span><div><p class="font-medium">{{m.nickname}}<span v-if="m.id===page.props.household.owner_member_id" class="badge ml-2">Owner</span></p><p class="help mt-1">{{m.email||'No login'}}</p></div></div><div class="flex items-center gap-3"><button class="btn min-h-8! text-xs!" @click="edit('member',m)">Edit</button><button v-if="page.props.household.owner&&m.user_id!==page.props.auth.id" class="link-danger text-xs!" @click="remove('/household/members/'+m.id,m)">Remove…</button></div></div></section>
  <section v-if="page.props.household.owner" class="panel"><div class="px-5 py-4"><h2>Pending invitations</h2><p class="help mt-1">Invitations appear when someone signs in with their Google email. They can also join through Profile.</p></div><div v-for="i in invitations" :key="i.id" class="flex items-center justify-between gap-3 border-t border-line-soft px-5 py-3"><div><p class="font-medium">{{i.target_email}}</p><p class="help mt-1">Invited {{dateLabel(i.created_at)}}</p></div><button class="btn min-h-8! text-xs!" @click="mutate('/household/invitations/'+i.id,{},'delete')">Cancel invitation</button></div><p v-if="!invitations.length" class="help border-t border-line px-5 py-5">No pending invitations. Invite someone so they can sign in and edit the shared records.</p></section>
  <section class="panel"><div class="flex items-center justify-between px-5 py-4"><div><h2>Bank connections</h2><p class="help mt-1">Shared by the household. Any member can manage imports.</p></div><Link v-if="providerReady" href="/connections/authorize" class="btn-primary"><Plus :size="14"/>Connect a bank</Link></div><p v-if="!providerReady" class="help px-5 pb-5">Bank connections are awaiting provider configuration. You can use manual accounts now.</p><div v-for="connection in connections" :key="connection.id" class="flex flex-wrap items-center justify-between gap-3 border-t border-line-soft px-5 py-4"><div class="flex items-start gap-3"><span class="avatar bg-ground! text-muted!"><Landmark :size="18"/></span><div><p class="font-medium">{{connection.name}}<span class="badge ml-2" :class="connection.state!=='active'?'badge-warning':''">{{connection.state.replaceAll('_',' ')}}</span></p><p class="help mt-1">{{connection.last_full_success_at?'Last full sync '+dateLabel(connection.last_full_success_at):'No full sync yet'}}</p><p v-if="connection.latest_error" class="help mt-1 text-warning">Latest sync failed. Successful account imports were retained.</p></div></div><div class="flex items-center gap-3"><button class="btn min-h-8! text-xs!" @click="connectionDetail=connection.id">Details</button><a v-if="connection.state!=='active'&&providerReady" :href="'/connections/authorize?reconnect='+connection.id" class="btn min-h-8! text-xs!">Reconnect</a><button v-if="connection.state==='active'" class="btn min-h-8! text-xs!" @click="mutate('/connections/'+connection.id+'/sync')"><RefreshCw :size="13"/>Sync now</button><button v-if="connection.state==='active'" class="link-danger text-xs!" @click="remove('/connections/'+connection.id,connection)">Remove…</button></div></div></section>
  <section v-if="page.props.household.owner" class="panel p-5"><h2>Transfer ownership</h2><p class="help mt-1">Only members signed in with Google can become owner. You stay in the household as a member.</p><button class="btn mt-4" @click="edit('owner',{})">Transfer ownership</button></section>
  <section class="panel overflow-hidden border-orange-200!"><h2 class="px-5 py-4 text-warning">Leave or delete</h2><div class="flex items-center justify-between gap-4 border-t border-line-soft px-5 py-4"><div><p class="font-medium">Leave household</p><p class="help mt-1">{{page.props.household.owner?'Transfer ownership first, then leave.':'Your assignments and financial history stay with the household.'}}</p></div><button class="btn" :disabled="page.props.household.owner" @click="leave">Leave…</button></div><div v-if="page.props.household.owner" class="flex items-center justify-between gap-4 border-t border-line-soft px-5 py-4"><div><p class="font-medium">Delete household</p><p class="help mt-1">Everyone loses access. This cannot be restored through the app.</p></div><button class="btn-destructive" @click="remove('/household',{name:page.props.household.name})">Delete household…</button></div></section>
 </div></template>
 <template v-else-if="section==='profile'"><div class="max-w-3xl space-y-5"><section class="panel flex items-center justify-between p-5"><div class="flex items-center gap-3"><span class="avatar size-12!">{{(profile?.name||page.props.auth.name).slice(0,2).toUpperCase()}}</span><div><p class="font-semibold">{{profile?.name||page.props.auth.name}}</p><p class="help mt-1">{{profile?.email||page.props.auth.email}}</p><p class="help mt-0.5">Signed in with Google</p></div></div><Link href="/logout" method="post" as="button" class="btn">Sign out</Link></section><ProfilePreferences v-if="profile" :profile="profile"/><section class="panel flex items-center justify-between p-5"><div><h2>Your household</h2><p class="help mt-1">{{page.props.household.name}} · {{page.props.household.owner?'Owner':'Member'}} · {{page.props.household.member_count}} members</p></div><Link href="/household" class="btn">Manage household</Link></section><section class="panel"><h2 class="px-5 py-4">Invitations</h2><div v-for="invitation in invitations" :key="invitation.id" class="border-t border-line-soft p-5"><div class="flex items-center justify-between gap-4"><div><p class="font-medium">{{invitation.household}}</p><p class="help mt-1">Invited by {{invitation.inviter}} · {{dateLabel(invitation.created_at)}}</p></div><div class="flex gap-2"><Link :href="'/invitations/'+invitation.id+'/decline'" method="post" as="button" class="btn">Decline</Link><button class="btn" @click="invitationReview=invitation.id">Review</button><button class="btn-primary" disabled>Accept</button></div></div><p class="help mt-3 rounded-md bg-ground p-3">You can belong to one household at a time. {{page.props.household.owner?'Transfer ownership and leave, or delete this household,':'Leave this household first'}} before accepting another invitation.</p></div><p v-if="!invitations.length" class="help border-t border-line px-5 py-5">No pending invitations for {{page.props.auth.email}}.</p></section></div></template>
 <template v-else-if="section==='notifications'"><div class="max-w-4xl"><div class="segmented mb-5"><Link v-for="[value,label] in [['all','All'],['unread','Unread'],['dismissed','Dismissed']]" :href="'/notifications?filter='+value" :aria-current="(filters?.filter||'all')===value?'page':undefined">{{label}}</Link></div><div class="panel overflow-hidden"><div v-for="notification in items" :key="notification.id" class="flex items-start justify-between gap-3 border-b border-line-soft px-4 py-4" :class="!notification.read_at?'bg-selected':''"><span class="mt-3 size-1.5 shrink-0 rounded-full" :class="!notification.read_at?'bg-income':'bg-transparent'"/><button class="flex flex-1 items-start gap-3 text-left" @click="openNotification(notification)"><span class="flex size-8 shrink-0 items-center justify-center rounded-md" :class="notification.kind.includes('budget')?'bg-warning-soft text-warning':'bg-ground text-muted'"><Bell :size="16"/></span><span><span class="block font-medium">{{notification.data.title}} <span v-if="notification.data.current_status" class="badge ml-1" :class="notification.data.current_status==='overdue'?'badge-warning':''">{{notification.data.current_status.replaceAll('_',' ')}}</span></span><span v-if="notification.data.due_date" class="help mt-1 block">Due {{dateLabel(notification.data.due_date)}} · {{money(notification.data.amount_cents)}}</span><span class="help mt-1 block">{{dateLabel(notification.created_at)}}</span></span></button><button class="text-xs text-muted hover:underline" @click="mutate('/notifications/'+notification.id+'/read',{unread:Boolean(notification.read_at)})">{{notification.read_at?'Mark unread':'Mark read'}}</button><button v-if="!notification.dismissed_at" class="icon-btn size-7!" aria-label="Dismiss notification" @click="mutate('/notifications/'+notification.id+'/dismiss')"><X :size="15"/></button></div><div v-if="!items.length" class="empty"><Bell :size="28"/><p class="font-medium text-ink">You’re all caught up</p><p class="help">Reminders, budget alerts and invitations appear here.</p></div><Pagination :records="records"/></div><p class="help mt-4">Headlines keep the original due date. Opening a notification marks it as read. Dismissed notifications stay available above.</p></div></template>
 <template v-else-if="section==='investments'"><InvestmentWorkspace :accounts="items" :detail="investment" @transaction="id=>transactionDetail=id"/></template>
 <InvitationReview v-if="invitationReview" :id="invitationReview" :can-accept="false" @close="invitationReview=undefined"/>
 <FinanceEditor v-if="editor" :key="editor.kind+(editor.record?.id||'new')" v-bind="editor" :catalog="catalog" :month="month" @close="editor=null" @cancel-subscription="record=>edit('cancel',record)"/>
 <AccountDetails v-if="accountDetail" :id="accountDetail" :catalog="catalog" @close="accountDetail=undefined" @edit="accountEdit" @connection="id=>{accountDetail=undefined;connectionDetail=id;}" @transaction="id=>{accountDetail=undefined;transactionDetail=id;}"/>
 <ConnectionDetails v-if="connectionDetail" :id="connectionDetail" :catalog="catalog" @close="connectionDetail=undefined"/>
 <TransactionDetails v-if="transactionDetail" :id="transactionDetail" :catalog="catalog" @close="transactionDetail=undefined" @edit="record=>{transactionDetail=undefined;edit('transaction',record);}" @remove="record=>{transactionDetail=undefined;remove('/transactions/'+record.id,record);}" @history="id=>{transactionDetail=undefined;showHistory('transactions',id);}" @payment="id=>{transactionDetail=undefined;occurrence=id;}"/>
 <OccurrencePanel v-if="occurrence" :id="occurrence" :catalog="catalog" @close="occurrence=undefined" @navigate="id=>occurrence=id" @edit="scheduleEdit" @remove="scheduleRemove"/>
 <Modal v-if="day" :open="true" :title="'Payments · '+dateLabel(day)" @close="day=undefined"><div class="p-6"><div class="mb-5 grid grid-cols-2 gap-3"><div v-for="[label,value] in [['Income',daySummary.income],['Payments due',daySummary.due],['Paid',daySummary.paid],['Still to pay',daySummary.unpaid]]" :key="label" class="rounded border border-line p-3"><p class="help">{{label}}</p><p class="money mt-1">{{money(Number(value))}}</p></div></div><p v-if="daySummary.unknown" class="help mb-4">Known subtotal · {{daySummary.unknown}} unknown amounts.</p><button v-for="item in dayItems(day)" :key="item.id" class="flex w-full items-center justify-between border-b border-line py-4 text-left hover:bg-zinc-50" @click="occurrence=item.id;day=undefined"><span>{{item.name}}<span class="help mt-1 block">{{item.status}}</span></span><span class="money">{{money(item.amount_cents)}}</span></button><p v-if="!dayItems(day).length" class="empty">No payments due.</p></div></Modal>
 <Modal v-if="drawer" :open="true" :title="drawer.title" @close="drawer=null"><div class="p-6"><HistoryPanel v-if="drawer.history" :events="drawer.history.data"/><Pagination v-if="drawer.history" :records="drawer.history" asynchronous @load="async (url:string)=>{try{drawer.history=await json(url);}catch(e:any){loadingError=e.message;}}"/>
  <template v-if="drawer.kind==='accounts'"><h3 class="mb-3 font-medium">Transactions</h3><div v-for="t in drawer.data.transactions.data" :key="t.id" class="flex justify-between border-b border-line py-3"><span>{{t.payee}}<span class="help mt-1 block">{{dateLabel(t.transaction_date)}}</span></span><span class="money">{{money(t.amount_cents)}}</span></div><Link :href="'/transactions?account='+drawer.record.id" class="btn mt-4" @click="drawer=null">View all transactions</Link><h3 class="mb-3 mt-6 font-medium">Balance observations</h3><div v-for="b in drawer.data.balances" :key="b.id" class="flex justify-between border-b border-line py-3"><span>{{dateLabel(b.effective_date)}}<span class="help mt-1 block">{{b.kind.replaceAll('_',' ')}}</span></span><span class="money">{{money(b.balance_cents)}}</span></div></template>
  <template v-if="drawer.kind==='loans'"><LoanChart :detail="drawer.data" :today="page.props.today"/><h3 class="mb-3 font-medium">Payment history</h3><div v-for="p in drawer.data.payments.data" :key="p.id" class="flex justify-between border-b border-line py-3"><span>{{dateLabel(p.payment_date)}}<span class="help mt-1 block">{{p.kind.replaceAll('_',' ')}}</span></span><div class="flex items-center gap-1"><span class="money">{{money(p.amount_cents)}}</span><template v-if="p.kind==='extra'||p.kind==='past_payment'"><button class="icon-btn" aria-label="Correct payment" @click="edit('payment',p,{endpoint:'/loan-payments/'+p.id});drawer=null"><Pencil :size="14"/></button><button class="icon-btn" aria-label="Remove payment" @click="remove('/loan-payments/'+p.id,p);drawer=null"><Trash2 :size="14"/></button></template></div></div><p v-if="!drawer.data.payments.data.length" class="help">No payments recorded yet.</p><Pagination :records="drawer.data.payments" asynchronous @load="drawerPage"/><h3 class="mb-3 mt-6 font-medium">Installments</h3><button v-for="o in drawer.data.installments?.data||[]" :key="o.id" class="flex w-full justify-between border-b border-line py-3 text-left" @click="occurrence=o.id;drawer=null"><span>{{dateLabel(o.due_date)}}<span class="help mt-1 block">{{o.status}}</span></span><span class="money">{{money(o.amount_cents)}}</span></button><Pagination :records="drawer.data.installments" asynchronous @load="drawerPage"/></template>
 </div></Modal>
</AppLayout></template>
